// Evidence Chain & Provenance System (Feature 25)
//
// Maintains complete, immutable, and auditable provenance for every finding,
// relationship, inference, and report generated by the platform.
//
// Every piece of intelligence is traceable back to its origin with enough detail
// to allow a reviewer to reconstruct how the conclusion was reached, what sources
// were used, when the evidence was collected, how it was normalized, and what
// confidence was assigned at each stage of processing.
//
// 10 provenance attribute groups:
//   1. Collector — subsystem, method, execution context, version
//   2. Tool — exact tool, version, config, mode, limitations
//   3. Timestamp — collected, source-observed, ingested, normalized, scored
//   4. Query — exact query, params, investigation context, normalized form
//   5. Source URL — canonical URL, multiple refs, source type, canonicalization
//   6. Raw response — original payload, hash, size, truncation, omission reason
//   7. Normalized data — structured representation, transformation steps, field mappings
//   8. Confidence — score, rationale, raw/normalized/inferred confidence, propagation
//   9. Relationships — derived entities/relationships, corroboration, contradictions
//  10. Audit metadata — actor, access context, processing status, integrity, compliance
//
// Lifecycle stages: collection → validation → normalization → deduplication →
//   entity_resolution → correlation → scoring → synthesis → reporting →
//   re_scoring → historical_comparison → audit_review

import { db } from "@/lib/db";
import { createHash } from "crypto";
import type { SourceResult, NormalizedFinding, DetectionResult } from "./types";
import { getReliabilityTier, type ReliabilityTier } from "./confidence-engine";
import { safeJsonStringArray, safeJsonObject } from "./safe-json";

// ============================================================================
// DOMAIN TYPES
// ============================================================================

export type ProvenanceEventType =
  | "collection"
  | "validation"
  | "normalization"
  | "deduplication"
  | "entity_resolution"
  | "correlation"
  | "scoring"
  | "synthesis"
  | "reporting"
  | "enrichment"
  | "re_scoring"
  | "correction"
  | "historical_comparison";

export type CollectionMethod =
  | "crawler" | "api_client" | "parser" | "enrichment_service"
  | "manual_import" | "ai_extraction" | "webhook";

export type ToolMode = "sync" | "async" | "batch" | "streaming";

export type SourceType = "primary" | "secondary" | "mirror" | "archive" | "cached";

export type ActorType = "system" | "agent" | "user" | "api";

export type ProcessingStatus = "active" | "deprecated" | "redacted" | "deleted";

export interface ProvenanceEvent {
  id: string;
  investigationId: string;
  evidenceId: string;
  parentEventId?: string;
  eventType: ProvenanceEventType;
  eventTime: string;

  // Collector
  collectorName: string;
  collectionMethod: CollectionMethod;
  executionContext: Record<string, string>;
  collectorVersion: string;

  // Tool
  toolName: string;
  toolVersion: string;
  toolConfig: Record<string, unknown>;
  toolMode: ToolMode;
  toolLimitations: string;

  // Timestamp
  collectedAt: string;
  sourceObservedAt?: string;
  ingestedAt: string;
  normalizedAt?: string;
  scoredAt?: string;

  // Query
  queryString: string;
  queryParams: Record<string, unknown>;
  investigationContext: string;
  queryNormalized: string;

  // Source URL
  sourceUrl: string;
  sourceUrls: string[];
  sourceType: SourceType;
  canonicalization: string;

  // Raw response
  rawPayload: string;
  rawHash: string;
  rawSize: number;
  rawTruncated: boolean;
  rawOmissionReason: string;

  // Normalized data
  normalizedData: Record<string, unknown>;
  transformationSteps: string[];
  fieldMappings: Record<string, string>;
  normalizationVersion: string;

  // Confidence
  confidence: number;
  confidenceRationale: string;
  rawConfidence: number;
  normalizedConfidence: number;
  confidencePropagation: Record<string, unknown>;

  // Relationships
  derivedEntities: string[];
  derivedRelationships: string[];
  corroboratingEvidence: string[];
  contradictingEvidence: string[];

  // Audit metadata
  actorId: string;
  actorType: ActorType;
  accessContext: Record<string, unknown>;
  processingStatus: ProcessingStatus;
  retentionPolicy: string;
  integrityHash: string;
  retryCount: number;
  errorState: string;
  latencyMs: number;
  pipelineStage: string;

  createdAt: string;
}

export interface ProvenanceChain {
  evidenceId: string;
  events: ProvenanceEvent[];
  totalEvents: number;
  collectionEvents: number;
  normalizationEvents: number;
  scoringEvents: number;
  synthesisEvents: number;
  reportingEvents: number;
  earliestEvent: string;
  latestEvent: string;
  sourceChain: { sourceUrl: string; sourceType: SourceType; collectedAt: string; collector: string }[];
  confidenceHistory: { timestamp: string; confidence: number; rationale: string; eventType: string }[];
  derivedFrom: string[]; // parent evidence IDs
  derivedInto: string[]; // child evidence IDs
}

export interface ProvenanceStats {
  totalEvents: number;
  eventsByType: Record<string, number>;
  eventsByCollector: Record<string, number>;
  eventsByTool: Record<string, number>;
  uniqueEvidenceIds: number;
  uniqueSourceUrls: number;
  avgConfidence: number;
  lowConfidenceCount: number;
  highConfidenceCount: number;
  errorCount: number;
  truncatedRawCount: number;
  timeline: { timestamp: string; eventType: string; count: number }[];
}

export interface ProvenanceQuery {
  investigationId?: string;
  evidenceId?: string;
  eventType?: ProvenanceEventType;
  collectorName?: string;
  toolName?: string;
  sourceUrl?: string;
  minConfidence?: number;
  maxConfidence?: number;
  startTime?: string;
  endTime?: string;
  processingStatus?: ProcessingStatus;
  limit?: number;
  offset?: number;
}

export interface ProvenanceReport {
  investigationId: string;
  totalEvents: number;
  uniqueEvidenceIds: number;
  stats: ProvenanceStats;
  recentEvents: ProvenanceEvent[];
  evidenceChains: { evidenceId: string; eventCount: number; latestEventType: string; latestConfidence: number }[];
  generatedAt: string;
}

// ============================================================================
// PROVENANCE RECORDER — immutable event creation
// ============================================================================

/**
 * Record a provenance event. This is the core function — all provenance
 * recording flows through here. Events are immutable once created.
 */
export async function recordProvenanceEvent(
  event: Omit<ProvenanceEvent, "id" | "createdAt" | "integrityHash">
): Promise<ProvenanceEvent> {
  const id = `prov_${randomId()}`;
  const now = new Date().toISOString();
  const integrityHash = computeIntegrityHash({ ...event, id, createdAt: now });

  const fullEvent: ProvenanceEvent = {
    ...event,
    id,
    createdAt: now,
    integrityHash,
  };

  try {
    await db.provenanceEvent.create({
      data: {
        id: fullEvent.id,
        investigationId: fullEvent.investigationId,
        evidenceId: fullEvent.evidenceId,
        parentEventId: fullEvent.parentEventId || null,
        eventType: fullEvent.eventType,
        eventTime: new Date(fullEvent.eventTime),

        collectorName: fullEvent.collectorName,
        collectionMethod: fullEvent.collectionMethod,
        executionContext: JSON.stringify(fullEvent.executionContext),
        collectorVersion: fullEvent.collectorVersion,

        toolName: fullEvent.toolName,
        toolVersion: fullEvent.toolVersion,
        toolConfig: JSON.stringify(fullEvent.toolConfig),
        toolMode: fullEvent.toolMode,
        toolLimitations: fullEvent.toolLimitations,

        collectedAt: new Date(fullEvent.collectedAt),
        sourceObservedAt: fullEvent.sourceObservedAt ? new Date(fullEvent.sourceObservedAt) : null,
        ingestedAt: new Date(fullEvent.ingestedAt),
        normalizedAt: fullEvent.normalizedAt ? new Date(fullEvent.normalizedAt) : null,
        scoredAt: fullEvent.scoredAt ? new Date(fullEvent.scoredAt) : null,

        queryString: fullEvent.queryString,
        queryParams: JSON.stringify(fullEvent.queryParams),
        investigationContext: fullEvent.investigationContext,
        queryNormalized: fullEvent.queryNormalized,

        sourceUrl: fullEvent.sourceUrl,
        sourceUrls: JSON.stringify(fullEvent.sourceUrls),
        sourceType: fullEvent.sourceType,
        canonicalization: fullEvent.canonicalization,

        rawPayload: fullEvent.rawPayload,
        rawHash: fullEvent.rawHash,
        rawSize: fullEvent.rawSize,
        rawTruncated: fullEvent.rawTruncated,
        rawOmissionReason: fullEvent.rawOmissionReason,

        normalizedData: JSON.stringify(fullEvent.normalizedData),
        transformationSteps: JSON.stringify(fullEvent.transformationSteps),
        fieldMappings: JSON.stringify(fullEvent.fieldMappings),
        normalizationVersion: fullEvent.normalizationVersion,

        confidence: fullEvent.confidence,
        confidenceRationale: fullEvent.confidenceRationale,
        rawConfidence: fullEvent.rawConfidence,
        normalizedConfidence: fullEvent.normalizedConfidence,
        confidencePropagation: JSON.stringify(fullEvent.confidencePropagation),

        derivedEntities: JSON.stringify(fullEvent.derivedEntities),
        derivedRelationships: JSON.stringify(fullEvent.derivedRelationships),
        corroboratingEvidence: JSON.stringify(fullEvent.corroboratingEvidence),
        contradictingEvidence: JSON.stringify(fullEvent.contradictingEvidence),

        actorId: fullEvent.actorId,
        actorType: fullEvent.actorType,
        accessContext: JSON.stringify(fullEvent.accessContext),
        processingStatus: fullEvent.processingStatus,
        retentionPolicy: fullEvent.retentionPolicy,
        integrityHash: fullEvent.integrityHash,
        retryCount: fullEvent.retryCount,
        errorState: fullEvent.errorState,
        latencyMs: fullEvent.latencyMs,
        pipelineStage: fullEvent.pipelineStage,

        createdAt: new Date(now),
      },
    });
  } catch (e) {
    console.error("[provenance] record failed", e instanceof Error ? e.message : String(e));
  }

  return fullEvent;
}

