/**
 * Record evidence collection from a source.
 */
export async function recordCollection(
  investigationId: string,
  evidenceId: string,
  source: string,
  sourceLabel: string,
  finding: NormalizedFinding,
  detection: DetectionResult,
  latencyMs: number,
  pipelineStage: string
): Promise<ProvenanceEvent> {
  const now = new Date().toISOString();
  const tier = getReliabilityTier(source);
  const rawPayload = finding.data.slice(0, 2000); // cap at 2KB
  const rawHash = computeHash(finding.data);
  const rawTruncated = finding.data.length > 2000;

  return recordProvenanceEvent({
    investigationId,
    evidenceId,
    eventType: "collection",
    eventTime: now,

    collectorName: `source-runner:${source}`,
    collectionMethod: "api_client",
    executionContext: {
      investigationId,
      target: detection.sanitized,
      inputType: detection.inputType,
    },
    collectorVersion: "1.0.0",

    toolName: sourceLabel,
    toolVersion: "unknown",
    toolConfig: { source, target: detection.sanitized },
    toolMode: "sync",
    toolLimitations: tier <= 2 ? "Low-credibility source — verify with higher-tier sources" : "",

    collectedAt: finding.timestamp,
    sourceObservedAt: finding.timestamp,
    ingestedAt: now,

    queryString: `query_${source}("${detection.sanitized}")`,
    queryParams: { target: detection.sanitized, inputType: detection.inputType },
    investigationContext: `Investigation of ${detection.sanitized} (${detection.inputType})`,
    queryNormalized: `${source}:${detection.sanitized.toLowerCase()}`,

    sourceUrl: finding.source_url,
    sourceUrls: [finding.source_url],
    sourceType: tier >= 4 ? "primary" : tier >= 3 ? "primary" : "secondary",
    canonicalization: "",

    rawPayload,
    rawHash,
    rawSize: finding.data.length,
    rawTruncated,
    rawOmissionReason: rawTruncated ? "Raw payload truncated to 2KB for storage" : "",

    normalizedData: {
      data: finding.data,
      source_url: finding.source_url,
      confidence: finding.confidence,
      timestamp: finding.timestamp,
      extra: finding.extra || {},
    },
    transformationSteps: ["raw_extraction", "field_mapping", "confidence_assignment"],
    fieldMappings: { raw_text: "data", url: "source_url", score: "confidence", time: "timestamp" },
    normalizationVersion: "1.0.0",

    confidence: finding.confidence,
    confidenceRationale: `Source tier ${tier} (${getSourceTierLabel(tier)}). Base confidence: ${finding.confidence}.`,
    rawConfidence: finding.confidence,
    normalizedConfidence: finding.confidence,
    confidencePropagation: { source: "raw_observation", method: "direct" },

    derivedEntities: [],
    derivedRelationships: [],
    corroboratingEvidence: [],
    contradictingEvidence: [],

    actorId: "system:pipeline",
    actorType: "system",
    accessContext: { investigationId },
    processingStatus: "active",
    retentionPolicy: "24h TTL",
    retryCount: 0,
    errorState: "",
    latencyMs,
    pipelineStage,
  });
}

