// ============================================================================
// PROVENANCE QUERY ENGINE
// ============================================================================

/**
 * Query provenance events with filters.
 */
export async function queryProvenanceEvents(query: ProvenanceQuery): Promise<ProvenanceEvent[]> {
  const where: Record<string, unknown> = {};
  if (query.investigationId) where.investigationId = query.investigationId;
  if (query.evidenceId) where.evidenceId = query.evidenceId;
  if (query.eventType) where.eventType = query.eventType;
  if (query.collectorName) where.collectorName = { contains: query.collectorName };
  if (query.toolName) where.toolName = { contains: query.toolName };
  if (query.sourceUrl) where.sourceUrl = { contains: query.sourceUrl };
  if (query.processingStatus) where.processingStatus = query.processingStatus;
  if (query.minConfidence !== undefined || query.maxConfidence !== undefined) {
    where.confidence = {};
    if (query.minConfidence !== undefined) (where.confidence as { gte?: number }).gte = query.minConfidence;
    if (query.maxConfidence !== undefined) (where.confidence as { lte?: number }).lte = query.maxConfidence;
  }
  if (query.startTime || query.endTime) {
    where.collectedAt = {};
    if (query.startTime) (where.collectedAt as { gte?: Date }).gte = new Date(query.startTime);
    if (query.endTime) (where.collectedAt as { lte?: Date }).lte = new Date(query.endTime);
  }

  const rows = await db.provenanceEvent.findMany({
    where,
    orderBy: { createdAt: "desc" },
    take: query.limit || 100,
    skip: query.offset || 0,
  });

  return rows.map(mapEvent);
}

/**
 * Get the full provenance chain for a specific evidence item.
 */
export async function getProvenanceChain(evidenceId: string): Promise<ProvenanceChain | null> {
  const events = await db.provenanceEvent.findMany({
    where: { evidenceId },
    orderBy: { eventTime: "asc" },
    take: 500,
  });

  if (events.length === 0) return null;

  const mappedEvents = events.map(mapEvent);

  const collectionEvents = mappedEvents.filter((e) => e.eventType === "collection").length;
  const normalizationEvents = mappedEvents.filter((e) => e.eventType === "normalization").length;
  const scoringEvents = mappedEvents.filter((e) => e.eventType === "scoring").length;
  const synthesisEvents = mappedEvents.filter((e) => e.eventType === "synthesis").length;
  const reportingEvents = mappedEvents.filter((e) => e.eventType === "reporting").length;

  const sourceChain = mappedEvents
    .filter((e) => e.sourceUrl)
    .map((e) => ({
      sourceUrl: e.sourceUrl,
      sourceType: e.sourceType,
      collectedAt: e.collectedAt,
      collector: e.collectorName,
    }));

  const confidenceHistory = mappedEvents
    .filter((e) => e.eventType === "scoring" || e.eventType === "collection" || e.eventType === "synthesis")
    .map((e) => ({
      timestamp: e.eventTime,
      confidence: e.confidence,
      rationale: e.confidenceRationale,
      eventType: e.eventType,
    }));

  const derivedFrom = [...new Set(mappedEvents.filter((e) => e.parentEventId).map((e) => e.parentEventId!))];

  // Find child evidence IDs (events where this evidenceId is a parent)
  const childEvents = await db.provenanceEvent.findMany({
    where: { parentEventId: { in: mappedEvents.map((e) => e.id) } },
    select: { evidenceId: true },
    distinct: ["evidenceId" as const],
    take: 50,
  });
  const derivedInto = childEvents.map((e) => e.evidenceId).filter((id) => id !== evidenceId);

  return {
    evidenceId,
    events: mappedEvents,
    totalEvents: mappedEvents.length,
    collectionEvents,
    normalizationEvents,
    scoringEvents,
    synthesisEvents,
    reportingEvents,
    earliestEvent: mappedEvents[0]?.eventTime || "",
    latestEvent: mappedEvents[mappedEvents.length - 1]?.eventTime || "",
    sourceChain,
    confidenceHistory,
    derivedFrom,
    derivedInto,
  };
}

/**
 * Get provenance stats for an investigation.
 */
export async function getProvenanceStats(investigationId: string): Promise<ProvenanceStats> {
  const events = await db.provenanceEvent.findMany({
    where: { investigationId },
    take: 10000,
  });

  if (events.length === 0) {
    return {
      totalEvents: 0,
      eventsByType: {},
      eventsByCollector: {},
      eventsByTool: {},
      uniqueEvidenceIds: 0,
      uniqueSourceUrls: 0,
      avgConfidence: 0,
      lowConfidenceCount: 0,
      highConfidenceCount: 0,
      errorCount: 0,
      truncatedRawCount: 0,
      timeline: [],
    };
  }

  const eventsByType: Record<string, number> = {};
  const eventsByCollector: Record<string, number> = {};
  const eventsByTool: Record<string, number> = {};
  const evidenceIds = new Set<string>();
  const sourceUrls = new Set<string>();
  let confSum = 0;
  let lowConf = 0;
  let highConf = 0;
  let errorCount = 0;
  let truncatedCount = 0;
  const timelineMap = new Map<string, { eventType: string; count: number }>();

  for (const e of events) {
    eventsByType[e.eventType] = (eventsByType[e.eventType] || 0) + 1;
    eventsByCollector[e.collectorName] = (eventsByCollector[e.collectorName] || 0) + 1;
    eventsByTool[e.toolName] = (eventsByTool[e.toolName] || 0) + 1;
    evidenceIds.add(e.evidenceId);
    if (e.sourceUrl) sourceUrls.add(e.sourceUrl);
    confSum += e.confidence;
    if (e.confidence < 0.4) lowConf++;
    if (e.confidence >= 0.7) highConf++;
    if (e.errorState) errorCount++;
    if (e.rawTruncated) truncatedCount++;

    const tsKey = new Date(e.eventTime).toISOString().slice(0, 19); // per-second
    const existing = timelineMap.get(tsKey);
    if (existing) {
      existing.count++;
    } else {
      timelineMap.set(tsKey, { eventType: e.eventType, count: 1 });
    }
  }

  const timeline = [...timelineMap.entries()]
    .map(([timestamp, val]) => ({ timestamp, eventType: val.eventType, count: val.count }))
    .sort((a, b) => a.timestamp.localeCompare(b.timestamp));

  return {
    totalEvents: events.length,
    eventsByType,
    eventsByCollector,
    eventsByTool,
    uniqueEvidenceIds: evidenceIds.size,
    uniqueSourceUrls: sourceUrls.size,
    avgConfidence: confSum / events.length,
    lowConfidenceCount: lowConf,
    highConfidenceCount: highConf,
    errorCount,
    truncatedRawCount: truncatedCount,
    timeline,
  };
}

/**
 * Get a full provenance report for an investigation.
 */
export async function getProvenanceReport(investigationId: string): Promise<ProvenanceReport> {
  const [stats, recentEvents, evidenceIds] = await Promise.all([
    getProvenanceStats(investigationId),
    db.provenanceEvent.findMany({
      where: { investigationId },
      orderBy: { createdAt: "desc" },
      take: 50,
    }),
    db.provenanceEvent.findMany({
      where: { investigationId },
      select: { evidenceId: true },
      distinct: ["evidenceId"],
      take: 200,
    }),
  ]);

  // Build evidence chain summaries
  const chainPromises = evidenceIds.slice(0, 50).map(async (e) => {
    const chain = await getProvenanceChain(e.evidenceId);
    if (!chain) return null;
    return {
      evidenceId: e.evidenceId,
      eventCount: chain.totalEvents,
      latestEventType: chain.events[chain.events.length - 1]?.eventType || "unknown",
      latestConfidence: chain.events[chain.events.length - 1]?.confidence || 0,
    };
  });
  const evidenceChains = (await Promise.all(chainPromises)).filter((c): c is NonNullable<typeof c> => c !== null);

  return {
    investigationId,
    totalEvents: stats.totalEvents,
    uniqueEvidenceIds: stats.uniqueEvidenceIds,
    stats,
    recentEvents: recentEvents.map(mapEvent),
    evidenceChains,
    generatedAt: new Date().toISOString(),
  };
}

// ============================================================================
// Mapping helpers
// ============================================================================

type ProvenanceRow = NonNullable<Awaited<ReturnType<typeof db.provenanceEvent.findUnique>>>;

function mapEvent(r: ProvenanceRow): ProvenanceEvent {
  return {
    id: r.id,
    investigationId: r.investigationId,
    evidenceId: r.evidenceId,
    parentEventId: r.parentEventId || undefined,
    eventType: r.eventType as ProvenanceEventType,
    eventTime: r.eventTime instanceof Date ? r.eventTime.toISOString() : String(r.eventTime),

    collectorName: r.collectorName,
    collectionMethod: r.collectionMethod as CollectionMethod,
    executionContext: safeJsonObject(r.executionContext) as Record<string, string>,
    collectorVersion: r.collectorVersion,

    toolName: r.toolName,
    toolVersion: r.toolVersion,
    toolConfig: safeJsonObject(r.toolConfig),
    toolMode: r.toolMode as ToolMode,
    toolLimitations: r.toolLimitations,

    collectedAt: r.collectedAt instanceof Date ? r.collectedAt.toISOString() : String(r.collectedAt),
    sourceObservedAt: r.sourceObservedAt instanceof Date ? r.sourceObservedAt.toISOString() : undefined,
    ingestedAt: r.ingestedAt instanceof Date ? r.ingestedAt.toISOString() : String(r.ingestedAt),
    normalizedAt: r.normalizedAt instanceof Date ? r.normalizedAt.toISOString() : undefined,
    scoredAt: r.scoredAt instanceof Date ? r.scoredAt.toISOString() : undefined,

    queryString: r.queryString,
    queryParams: safeJsonObject(r.queryParams),
    investigationContext: r.investigationContext,
    queryNormalized: r.queryNormalized,

    sourceUrl: r.sourceUrl,
    sourceUrls: safeJsonStringArray(r.sourceUrls),
    sourceType: r.sourceType as SourceType,
    canonicalization: r.canonicalization,

    rawPayload: r.rawPayload,
    rawHash: r.rawHash,
    rawSize: r.rawSize,
    rawTruncated: r.rawTruncated,
    rawOmissionReason: r.rawOmissionReason,

    normalizedData: safeJsonObject(r.normalizedData),
    transformationSteps: safeJsonStringArray(r.transformationSteps),
    fieldMappings: safeJsonObject(r.fieldMappings) as Record<string, string>,
    normalizationVersion: r.normalizationVersion,

    confidence: r.confidence,
    confidenceRationale: r.confidenceRationale,
    rawConfidence: r.rawConfidence,
    normalizedConfidence: r.normalizedConfidence,
    confidencePropagation: safeJsonObject(r.confidencePropagation),

    derivedEntities: safeJsonStringArray(r.derivedEntities),
    derivedRelationships: safeJsonStringArray(r.derivedRelationships),
    corroboratingEvidence: safeJsonStringArray(r.corroboratingEvidence),
    contradictingEvidence: safeJsonStringArray(r.contradictingEvidence),

    actorId: r.actorId,
    actorType: r.actorType as ActorType,
    accessContext: safeJsonObject(r.accessContext),
    processingStatus: r.processingStatus as ProcessingStatus,
    retentionPolicy: r.retentionPolicy,
    integrityHash: r.integrityHash,
    retryCount: r.retryCount,
    errorState: r.errorState,
    latencyMs: r.latencyMs,
    pipelineStage: r.pipelineStage,

    createdAt: r.createdAt instanceof Date ? r.createdAt.toISOString() : String(r.createdAt),
  };
}

// ============================================================================
// Utilities
// ============================================================================

function computeHash(data: string): string {
  return createHash("sha256").update(data).digest("hex").slice(0, 32);
}

function computeIntegrityHash(event: Record<string, unknown>): string {
  // Hash key fields for tamper detection
  const keyData = `${event.id}|${event.evidenceId}|${event.eventType}|${event.eventTime}|${event.confidence}|${event.sourceUrl}`;
  return computeHash(keyData);
}

function randomId(): string {
  return Math.random().toString(16).slice(2, 14) + Date.now().toString(16).slice(-4);
}

function getSourceTierLabel(tier: ReliabilityTier): string {
  const labels: Record<ReliabilityTier, string> = {
    5: "Authoritative",
    4: "Major threat intel",
    3: "Established data",
    2: "Community/aggregate",
    1: "Unverified",
  };
  return labels[tier];
}
